preConditionHook:
// Entry & Exit Confessions #14 (Split Week), verbatim: on Tue/Wed/Thu, a joint
// highest-high AND highest-close (lowest-low / lowest-close short) while the
// ATR in dollars is below maxl. The book's Condition1 is inlined -- it was
// assigned unconditionally every bar, so the OR of days is the same test.
// EL DayOfWeek(Date): 0 = Sunday .. 6 = Saturday, of the bar's wall-clock
// close date (EL_Date_Probe.txt, 169/169 incl. evening bars). day_of_week()
// in time.h uses the same numbering.
dow = day_of_week(day_of(ctx.Time(0)));
highestHigh = high[0];
lowestLow = low[0];
// Mirrors EasyLanguage's Extremes(), which Highest()/Lowest() call: seeded
// at bar 0, scanning bars 1..Length-1, strict comparison (so a tie keeps the
// earliest bar). Extremes is EL SOURCE, so its comparison carries the EL
// tolerance -- el_gt/el_lt, as in Breakout (the reference).
for (int i = 1; i < (int)bbars; ++i) {
    if (el_gt(high[i], highestHigh)) highestHigh = high[i];
    if (el_lt(low[i], lowestLow)) lowestLow = low[i];
}
highestClose = close[0];
lowestClose = close[0];
// Mirrors EasyLanguage's Extremes(), which Highest()/Lowest() call: seeded
// at bar 0, scanning bars 1..Length-1, strict comparison (so a tie keeps the
// earliest bar). Extremes is EL SOURCE, so its comparison carries the EL
// tolerance -- el_gt/el_lt, as in Breakout (the reference).
for (int i = 1; i < (int)bbars; ++i) {
    if (el_gt(close[i], highestClose)) highestClose = close[i];
    if (el_lt(close[i], lowestClose)) lowestClose = close[i];
}
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and thereafter updated as
// TWO statements -- EL evaluates S[1] + in - out left to right, and folding
// it to S += in - out rounds differently (@OJ 2015-02-20). The book calls
// plain AvgTrueRange; the standing decision (AI-Algos book, 2026-08-25) is
// that every ATR compares against the WFSafe_ override.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
